// Turn the product list into one item per product. Each entry can optionally
// carry your own price after an '=' (e.g. "sony wh-1000xm5=300") so we can flag
// when a competitor undercuts you.
const cfg = $('Settings').first().json;
const location = (cfg.location || 'United States').trim();

const entries = String(cfg.products || '')
  .split(',').map(s => s.trim()).filter(s => s.length);

if (!entries.length) {
  throw new Error('No products found. Add a comma-separated list in the Settings node.');
}

return entries.map(entry => {
  let product = entry;
  let your_price = null;
  const eq = entry.lastIndexOf('=');
  if (eq > 0) {
    const p = parseFloat(entry.slice(eq + 1).replace(/[^0-9.]/g, ''));
    if (!isNaN(p)) { product = entry.slice(0, eq).trim(); your_price = p; }
  }
  return { json: { product, location, your_price } };
});

// For each product: typical (median) NEW price + lowest legit offer, compared to
// the last run. If you set your own price (Settings: name=PRICE), also flag when
// a competitor undercuts you and whether that undercut is new this run.

const MIN_RATIO = 0.5;      // for the lowest price, ignore offers below 50% of the typical price
const EXCLUDE_USED = true;  // ignore used / refurbished listings (backstop to condition=new)

function num(v) {
  if (typeof v === 'number') return v;
  if (v == null) return null;
  const m = String(v).replace(/[^0-9.]/g, '');
  return m ? parseFloat(m) : null;
}
function isUsed(c) { return /refurb|renew|pre.?owned|used|open.?box|second/i.test(String(c || '')); }
function median(a) {
  if (!a.length) return null;
  const s = [...a].sort((x, y) => x - y);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
}
function round2(n) { return Math.round(n * 100) / 100; }

// Your price per product, from Split Products (entries like "name=300").
const yourPrice = {};
try {
  for (const it of $('Split Products').all()) {
    const j = it.json || {};
    if (j.product) yourPrice[String(j.product).trim()] = (typeof j.your_price === 'number') ? j.your_price : null;
  }
} catch (e) {}

// Previous typical price + undercut state per product, from the Latest tab.
const previous = {};
let history = [];
try { history = $('Get Price History').all(); } catch (e) { history = []; }
for (const row of history) {
  const r = row.json || {};
  const p = String(r.product || '').trim();
  if (!p) continue;
  previous[p] = {
    price: num(r.typical_price != null ? r.typical_price : r.price),
    undercut: String(r.undercut).toLowerCase() === 'true'
  };
}

const now = new Date().toISOString();
const results = [];

for (const item of $input.all()) {
  const resp = item.json || {};
  const sp = resp.search_parameters || {};
  const product = String(sp.q || resp.product || '').trim();
  if (!product) continue;

  let offers = (Array.isArray(resp.shopping_results) ? resp.shopping_results : [])
    .map(o => ({
      price: num(o.extracted_price != null ? o.extracted_price : o.price),
      seller: o.seller || o.merchant || o.source || '',
      link: o.product_link || o.link || '',
      condition: o.condition
    }))
    .filter(o => o.price != null && o.price > 0);
  if (EXCLUDE_USED) offers = offers.filter(o => !isUsed(o.condition));

  const typical = median(offers.map(o => o.price));
  const floor = typical != null ? typical * MIN_RATIO : 0;
  const legit = offers.filter(o => o.price >= floor);
  let low = null;
  for (const o of (legit.length ? legit : offers)) {
    if (!low || o.price < low.price) low = o;
  }

  const typicalPrice = typical != null ? round2(typical) : null;
  const lowPrice = low ? round2(low.price) : null;

  const yp = yourPrice[product];
  const your_price = (typeof yp === 'number') ? yp : null;
  const undercut = (your_price != null && lowPrice != null) ? lowPrice < your_price : false;
  const gap_to_you = (your_price != null && lowPrice != null) ? round2(lowPrice - your_price) : null;

  const prev = previous[product];
  const hasPrev = prev && typeof prev.price === 'number';
  const prevUndercut = prev ? !!prev.undercut : false;
  const newly_undercut = undercut && !prevUndercut;

  let change = null, pct = null, movement = '';
  if (typicalPrice == null) movement = 'No offers found';
  else if (!hasPrev) movement = 'New';
  else {
    change = round2(typicalPrice - prev.price);
    pct = prev.price ? Math.round((change / prev.price) * 1000) / 10 : null;
    movement = change < 0 ? 'Down' : (change > 0 ? 'Up' : 'No change');
  }

  results.push({ json: {
    product,
    typical_price: typicalPrice,
    low_price: lowPrice,
    low_seller: low ? low.seller : '',
    offers_count: offers.length,
    your_price,
    undercut,
    gap_to_you,
    prev_price: hasPrev ? prev.price : null,
    change, pct, movement,
    newly_undercut,
    is_new: !hasPrev && typicalPrice != null,
    url: low ? low.link : '',
    checked_at: now
  }});
}

results.sort((a, b) => {
  const av = a.json.change == null ? -1 : Math.abs(a.json.change);
  const bv = b.json.change == null ? -1 : Math.abs(b.json.change);
  return bv - av;
});
return results;

// Build a Slack alert. Only "notable" items are shown: the typical price moved
// beyond the alert threshold, a competitor newly undercut you, or the product is
// first-seen. The notable flag lets the Alert Gate mute days with no news.
const rows = $input.all().map(i => i.json);
const cfg = $('Settings').first().json;
const ALERT_PCT = Number(cfg.alert_pct) || 0;
const ALERT_ABS = Number(cfg.alert_abs) || 0;
const date = new Date().toISOString().slice(0, 10);

function money(v) { return v == null ? '-' : '$' + Number(v).toFixed(2); }
function moved(r) {
  if (r.change == null) return false;
  return Math.abs(r.change) >= ALERT_ABS || (r.pct != null && Math.abs(r.pct) >= ALERT_PCT);
}
function isNotable(r) { return moved(r) || r.newly_undercut || r.is_new; }

function icon(r) {
  if (r.newly_undercut) return ':rotating_light:';
  if (r.typical_price == null) return ':warning:';
  if (r.is_new) return ':new:';
  if (r.change < 0) return ':small_red_triangle_down:';
  if (r.change > 0) return ':small_red_triangle:';
  return ':white_circle:';
}
function detail(r) {
  if (r.typical_price == null) return 'no offers found';
  let s = '*' + money(r.typical_price) + '* typical';
  if (r.prev_price == null) s += '  (new)';
  else if (r.change === 0) s += '  (no change)';
  else {
    const sign = r.change < 0 ? '-' : '+';
    const pctStr = r.pct == null ? '' : ' / ' + (r.pct > 0 ? '+' : '') + r.pct + '%';
    s += '  (' + sign + '$' + Math.abs(r.change).toFixed(2) + pctStr + ')';
  }
  if (r.low_price != null) s += '  ·  low ' + money(r.low_price) + (r.low_seller ? ' @ ' + r.low_seller : '');
  if (r.undercut) s += '  ·  :rotating_light: under your ' + money(r.your_price);
  return s;
}

const shown = rows.filter(isNotable);
const notable = shown.length > 0;

shown.sort((a, b) => {
  const d = (b.newly_undercut ? 1 : 0) - (a.newly_undercut ? 1 : 0);
  if (d) return d;
  const av = a.change == null ? -1 : Math.abs(a.change);
  const bv = b.change == null ? -1 : Math.abs(b.change);
  return bv - av;
});

const lines = shown.map(r => icon(r) + '  *' + r.product + '*  -  ' + detail(r));
const undercutNow = rows.filter(r => r.undercut).length;

let summary = shown.length + ' of ' + rows.length + ' products flagged';
if (undercutNow) summary += '  ·  ' + undercutNow + ' undercutting you';

const body = lines.length ? lines.join('\n') : 'No notable price changes.';
const text = 'Competitor Price Monitor (' + date + ')\n' + body + '\n' + summary;

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: ':shopping_trolley: Competitor Price Monitor', emoji: true } },
  { type: 'context', elements: [ { type: 'mrkdwn', text: 'Google Shopping  ·  ' + date } ] },
  { type: 'divider' },
  { type: 'section', text: { type: 'mrkdwn', text: body } },
  { type: 'divider' },
  { type: 'context', elements: [ { type: 'mrkdwn', text: summary } ] }
];

return [{ json: { notable, text, blocks: JSON.stringify({ blocks }) } }];
